import {defaults,seed,blank,calculate,factor,ntuRow} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Math.round(n).toLocaleString('vi-VN')+' đ',pct=n=>(n*100).toLocaleString('vi-VN',{maximumFractionDigits:3})+'%',key='hanh-mix-v1';let state;try{state=JSON.parse(localStorage.getItem(key));}catch{}if(!state?.months)state={month:'2026-11',months:{'2026-11':seed()}};let tab='overview',list='cash',scenario=null;const data=()=>state.months[state.month];$('#month').value=state.month;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600);}function save(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{toast('Không lưu được. Hãy xuất bản sao lưu ngay.');return false;}}function row(a,b){return `<div class="row"><span>${a}</span><span>${b}</span></div>`;}function field(label,name,value,type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''} ${extra}></label>`;}const kinds=[['period','Thu kỳ'],['overdue','Thu quá hạn'],...Array.from({length:10},(_,i)=>['b'+(i+3),'Thanh lý B'+(i+3)]),['cof','Thanh lý COF / NON 13+ / PDS · 1,5'],['exception','Ngoại lệ']];function select(label,name,value,items){return `<label>${label}<select name="${name}">${items.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}function title(t,s){return `<h1>${t}</h1><p class="muted">${s}</p>`;}
function overview(){const d=data(),s=d.settings,c=calculate(d),next=s.bands.bonus.find(x=>x[0]>c.total+1e-12);return title('Tháng của bạn','Tiến độ thu và thu nhập, ở cùng một nơi.')+`<div class="hero"><small>THỰC NHẬN DỰ KIẾN</small><strong>${money(c.net)}</strong>${row('Trước thuế',money(c.gross))}${row('Thuế tạm tính',money(c.tax))}</div><div class="grid"><div><div class="card"><h2>Tiến độ chỉ tiêu</h2>${[['COF',c.kcof,money(c.cof)],['NON',c.knon,money(c.non)],['NTU CIC OK',c.ntuKpi,s.done+' / '+s.ntu+' hồ sơ']].map(([n,v,x])=>row(n,`<b>${pct(v)}</b><small>${x}</small>`)+`<div class="bar"><i style="width:${Math.min(100,Math.max(0,v*100))}%"></i></div>`).join('')}${row('KPI tiền',pct(c.cashKpi))}${row('<b>Tổng hoàn thành</b>',`<b>${pct(c.total)}</b>`)}<span class="tag">${next?'Mốc bonus tiếp theo: '+pct(next[0]):'Đã ở bậc bonus cao nhất'}</span>${s.cof===0||s.non===0||s.ntu===0?'<p class="warning">Target bằng 0: KPI tương ứng đang tính bằng 0. Hãy kiểm tra tham số.</p>':''}</div><div class="card"><h2>Điều kiện NTU quay đầu</h2>${row('POS đã bật',money(c.lit))}${row('Tổng POS được giao',money(c.ntuPos))}${row('Tỷ lệ POS đã bật',pct(c.ratio))}<div class="bar"><i style="width:${Math.min(100,c.ratio*100)}%"></i></div>${row('Thiếu tới 68%',money(Math.max(0,.68*c.ntuPos-c.lit)))}${row('Thiếu tới 85%',money(Math.max(0,.85*c.ntuPos-c.lit)))}<span class="tag">${c.ratio>=.85?'Đủ bonus + trách nhiệm':c.ratio>=.68?'Đủ bonus · chưa nhận trách nhiệm':'Hưởng 80% bonus'}</span>${!c.ntuPos?'<p class="muted">Chưa có POS NTU: chưa xác định đủ điều kiện, đang tạm áp 80% bonus.</p>':''}</div></div><div><div class="card"><h2>Cơ cấu thu nhập</h2>${row('POS quy đổi',money(c.pos))}${row('Tỷ lệ thưởng',pct(c.bonusRate))}${row('Bonus phát sinh',money(c.bonus))}${row('Bonus được hưởng',money(c.paidBonus))}${row('Trách nhiệm đã tính',money(c.responsibility))}${row('Trách nhiệm được nhận',money(c.paidResponsibility))}${row('Lương cứng',money(s.salary))}</div><div class="card"><h2>Đối chiếu tiền công ty</h2>${row('COF + NON',money(c.cof+c.non))}${row('Tiền NTU quay đầu',money(c.actual-c.cof-c.non))}${row('<b>Tổng thực thu</b>',`<b>${money(c.actual)}</b>`)}${field('Công ty ghi nhận (đ)','company',s.company??'')}<button data-action="company">Lưu số đối chiếu</button>${row('Tự theo dõi − công ty',s.company===null?'Chưa nhập':money(c.actual-s.company))}</div></div></div><p class="muted">Dữ liệu lưu trên trình duyệt này. Thuế tính theo tham số tháng, chưa được xác minh pháp lý. Số khởi tạo lấy từ cuộc trao đổi; không tự cập nhật Google Sheets.</p>`;}
function entry(d=data(),sim=false){const rows=d[list];return `${sim?'':title('Nhập thu','Mỗi hợp đồng một dòng · Nhập tiền lũy kế trong tháng.')}<div class="actions"><button data-list="cash" class="${list==='cash'?'primary':''}">COF / NON (${d.cash.length})</button><button data-list="ntu" class="${list==='ntu'?'primary':''}">NTU quay đầu (${d.ntu.length})</button><button class="primary" data-action="add">＋ Thêm hồ sơ</button></div>${rows.length?rows.map(r=>{const n=list==='ntu'?ntuRow(r):null;return `<article class="list-item"><div class="list-top"><div><b>${esc(r.name||'Chưa có tên')}</b><small>${esc(r.contract||'Chưa nhập số hợp đồng')}</small></div><button data-edit="${esc(r.id)}">Sửa</button></div>${row('Tiền lũy kế',`<b>${money(r.amount)}</b>`)}${n?row('POS bật / tiền trách nhiệm',`${n.lit?money(n.lit):'—'}<small>${money(n.responsibility)} · Hệ số ${pct(n.hs)}</small>`):row(`${esc(r.group)} · ${esc(kinds.find(x=>x[0]===r.kind)?.[1]||'')}`,`POS quy đổi ${money(r.amount*factor(r))}`)}${n?`<span class="tag">${n.liquidated?'Thanh lý':n.active?'Đủ mindue':'Chưa đủ mindue'}</span>`:''}</article>`;}).join(''):'<div class="empty">Chưa có hồ sơ. Bấm “Thêm hồ sơ” để bắt đầu.</div>'}`;}
function simulation(){if(!scenario)scenario=structuredClone(data());const a=calculate(data()),b=calculate(scenario);return title('Thử trước, quyết định sau','Bản sao độc lập. Thay số tiền, kiểu thu hoặc NTU để xem toàn bộ tác động.')+`<div class="hero"><small>THỰC NHẬN SAU MÔ PHỎNG</small><strong>${money(b.net)}</strong>${row('Chênh lệch so với thực tế',(b.net-a.net>=0?'+':'')+money(b.net-a.net))}</div><div class="actions"><button data-action="reset-sim">Lấy lại số thực tế</button></div><div class="card tablewrap"><table><thead><tr><th>Chỉ tiêu</th><th>Thực tế</th><th>Mô phỏng</th></tr></thead><tbody>${[['Tổng hoàn thành','total',pct],['POS quy đổi','pos',money],['Bonus được nhận','paidBonus',money],['Trách nhiệm được nhận','paidResponsibility',money],['Trước thuế','gross',money],['Thuế','tax',money],['Thực nhận','net',money]].map(([t,k,f])=>`<tr><td>${t}</td><td>${f(a[k])}</td><td>${f(b[k])}</td></tr>`).join('')}</tbody></table></div><div class="card"><label>Số NTU CIC OK giả định<input id="sim-done" type="number" min="0" step="1" value="${scenario.settings.done}"></label><button data-action="sim-done">Tính lại</button></div>${entry(scenario,true)}`;}
const settingFields=[['cof','Target COF (đ)'],['non','Target NON (đ)'],['ntu','Target NTU'],['done','NTU CIC OK đã hoàn thành'],['wcof','Trọng số COF (0,4 = 40%)'],['wnon','Trọng số NON (0,6 = 60%)'],['salary','Lương cứng (đ)'],['dependents','Số người phụ thuộc'],['deduct','Giảm trừ bản thân (đ)'],['perDependent','Giảm trừ mỗi người phụ thuộc (đ)'],['insurance','Bảo hiểm được giảm trừ (đ)']];
function settings(){const s=data().settings;return title('Tham số theo tháng','Mỗi tháng giữ bộ target, lương và hệ số riêng.')+`<form id="settings-form"><div class="card"><h2>Chỉ tiêu & thu nhập</h2><div class="split">${settingFields.map(([k,n])=>field(n,k,s[k])).join('')}</div><details><summary>Bảng hệ số và biểu thuế</summary><p class="muted">Mỗi dòng: ngưỡng bắt đầu, hệ số. Tỷ lệ dùng số thập phân: 0.8 = 80%. Ngưỡng phải tăng dần và bắt đầu từ 0.</p>${[['ntu','KPI tiền → hệ số NTU'],['cash','KPI NTU → hệ số tiền'],['bonus','Tổng hoàn thành → tỷ lệ bonus']].map(([k,n])=>`<label>${n}<textarea name="band-${k}">${s.bands[k].map(r=>r.join(', ')).join('\n')}</textarea></label>`).join('')}<label>Biểu thuế: thu nhập tính thuế từ, thuế suất<textarea name="taxBands">${s.taxBands.map(r=>r.join(', ')).join('\n')}</textarea></label><p class="warning">Các mức thuế khởi tạo sao chép từ bảng nguồn, chưa xác minh quy định hiện hành.</p></details><button class="primary" type="submit">Lưu tham số tháng</button></div></form><div class="card"><h2>Sao lưu & chuyển thiết bị</h2><p class="muted">Không tự đồng bộ giữa điện thoại và máy tính. Xuất bản sao lưu trước khi xóa dữ liệu trình duyệt.</p><div class="actions"><button data-action="export">Xuất toàn bộ dữ liệu</button><button data-action="import">Nhập bản sao lưu</button></div><input type="file" id="import-file" accept="application/json,.json" hidden></div>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#app').innerHTML=tab==='overview'?overview():tab==='entry'?entry():tab==='sim'?simulation():settings();if($('#settings-form'))$('#settings-form').addEventListener('submit',saveSettings);if($('#import-file'))$('#import-file').addEventListener('change',importFile);}
function parseBands(text){const a=text.trim().split(/\n+/).map(l=>l.split(',').map(Number));if(!a.length||a[0][0]!==0||a.some((r,i)=>r.length!==2||r.some(v=>!Number.isFinite(v)||v<0)||r[1]>1||(i&&r[0]<=a[i-1][0])))throw Error('Bảng hệ số không hợp lệ.');return a;}
function saveSettings(e){e.preventDefault();const f=new FormData(e.target),s=structuredClone(data().settings);try{for(const [k]of settingFields){s[k]=Number(f.get(k));if(!Number.isFinite(s[k])||s[k]<0)throw Error('Tham số phải là số không âm.');}if(Math.abs(s.wcof+s.wnon-1)>1e-8)throw Error('Tổng trọng số COF và NON phải bằng 1.');for(const k of ['ntu','done','dependents'])if(!Number.isInteger(s[k]))throw Error('Số hồ sơ và người phụ thuộc phải là số nguyên.');for(const k of ['ntu','cash','bonus'])s.bands[k]=parseBands(f.get('band-'+k));s.taxBands=parseBands(f.get('taxBands'));data().settings=s;save();toast('Đã lưu tham số tháng.');render();}catch(err){toast(err.message);}}
function editor(id){const d=tab==='sim'?scenario:data(),existing=d[list].find(r=>r.id===id),r=existing||{id:crypto.randomUUID(),name:'',contract:'',amount:0,group:'COF',kind:'period',manual:list==='cash'?1:.05,pos:0,mindue:0,override:null};$('#record-form').innerHTML=`<h2>${existing?'Sửa':'Thêm'} ${list==='cash'?'khoản thu':'NTU quay đầu'}${tab==='sim'?' · Mô phỏng':''}</h2>${field('Tên khách hàng','name',r.name,'text','required')}${field('Số hợp đồng','contract',r.contract,'text')}${field('Tổng tiền đã thu trong tháng (đ)','amount',r.amount)}${list==='cash'?select('Phân loại','group',r.group,[['COF','COF'],['NON','NON']])+select('Kiểu thu cuối cùng','kind',r.kind,kinds)+field('Hệ số riêng (chỉ dùng khi Ngoại lệ)','manual',r.manual):`<div class="split">${field('POS được giao (đ)','pos',r.pos,'number','required')}${field('Mindue (đ)','mindue',r.mindue,'number','required')}</div>${select('Hệ số thủ công ban đầu','manual',String(r.manual),[['0.05','5%'],['0.1','10%'],['0.15','15%'],['0.2','20%']])}${field('Ghi đè hệ số hiện tại (để trống: tự động)','override',r.override??'')}<p class="muted">Đủ thanh lý: tự dùng 20%; chưa thanh lý: dùng mức đã chọn. Ghi đè được ưu tiên và sẽ tự xóa khi chuyển trạng thái thanh lý.</p>`}<div class="actions"><button type="submit" class="primary">Lưu</button><button type="button" id="cancel">Hủy</button>${existing?'<button type="button" class="danger" id="delete">Xóa hồ sơ</button>':''}</div>`;$('#cancel').onclick=()=>$('#editor').close();if($('#delete'))$('#delete').onclick=()=>{if(confirm('Xóa hồ sơ này?')){d[list]=d[list].filter(x=>x.id!==r.id);if(tab!=='sim')save();$('#editor').close();render();}};$('#record-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),n={...r,name:String(f.get('name')).trim(),contract:String(f.get('contract')).trim(),amount:Number(f.get('amount')),manual:Number(f.get('manual'))};if(!n.name||!Number.isFinite(n.amount)||n.amount<0||!Number.isFinite(n.manual)||n.manual<0){toast('Kiểm tra tên, tiền thu và hệ số.');return;}if(n.contract&&d[list].some(x=>x.id!==n.id&&x.contract===n.contract)){toast('Số hợp đồng đã tồn tại trong bảng này.');return;}if(list==='cash'){n.group=f.get('group');n.kind=f.get('kind');}else{n.pos=Number(f.get('pos'));n.mindue=Number(f.get('mindue'));n.override=f.get('override')===''?null:Number(f.get('override'));if(n.pos<=0||n.mindue<=0||!Number.isFinite(n.pos)||!Number.isFinite(n.mindue)||n.manual>1||(n.override!==null&&(!Number.isFinite(n.override)||n.override<0||n.override>1))){toast('POS, mindue phải lớn hơn 0; hệ số từ 0 đến 1.');return;}if(existing&&ntuRow(r).liquidated!==(n.amount>=n.pos)&&n.override===r.override)n.override=null;}if(existing)d[list][d[list].findIndex(x=>x.id===n.id)]=n;else d[list].push(n);if(tab!=='sim')save();$('#editor').close();render();};$('#editor').showModal();}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='HANH-sao-luu-'+state.month+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validBackup(x){if(!x||typeof x.month!=='string'||!x.months||!x.months[x.month])return false;for(const [m,d]of Object.entries(x.months)){if(!/^\d{4}-\d{2}$/.test(m)||!d?.settings||!Array.isArray(d.cash)||!Array.isArray(d.ntu))return false;for(const[k]of settingFields)if(!Number.isFinite(d.settings[k])||d.settings[k]<0)return false;if(Math.abs(d.settings.wcof+d.settings.wnon-1)>1e-8)return false;for(const k of ['ntu','cash','bonus'])parseBands(d.settings.bands[k].map(r=>r.join(',')).join('\n'));parseBands(d.settings.taxBands.map(r=>r.join(',')).join('\n'));for(const r of [...d.cash,...d.ntu])if(typeof r.id!=='string'||typeof r.name!=='string'||typeof r.contract!=='string'||!Number.isFinite(r.amount)||r.amount<0||!Number.isFinite(r.manual)||r.manual<0)return false;for(const r of d.cash)if(!['COF','NON'].includes(r.group)||!kinds.some(k=>k[0]===r.kind))return false;for(const r of d.ntu)if(!Number.isFinite(r.pos)||r.pos<=0||!Number.isFinite(r.mindue)||r.mindue<=0||r.manual>1||(r.override!==null&&(!Number.isFinite(r.override)||r.override<0||r.override>1)))return false;if(!Number.isFinite(calculate(d).net))return false;}return true;}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Bản sao lưu quá lớn.');const x=JSON.parse(await file.text());if(!validBackup(x))throw Error('Bản sao lưu không hợp lệ.');if(!confirm('Nhập bản sao lưu sẽ thay toàn bộ dữ liệu trên trình duyệt này. Tiếp tục?'))return;state=x;scenario=null;$('#month').value=state.month;save();render();toast('Đã khôi phục bản sao lưu.');}catch(err){toast(err.message||'Không đọc được bản sao lưu.');}}
document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;render();window.scrollTo(0,0);});$('#month').addEventListener('change',e=>{if(!e.target.value)return;const m=e.target.value;if(!state.months[m]){if(!confirm('Tạo tháng mới với danh sách trống? Tham số được sao chép từ tháng hiện tại.')){e.target.value=state.month;return;}const d=blank();d.settings=structuredClone(data().settings);d.settings.done=0;d.settings.company=null;state.months[m]=d;}state.month=m;scenario=null;save();render();});$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.list){list=b.dataset.list;render();return;}if(b.dataset.edit){editor(b.dataset.edit);return;}switch(b.dataset.action){case'add':editor();break;case'company':{const v=$('[name=company]').value;if(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0)){toast('Số đối chiếu phải không âm.');break;}data().settings.company=v===''?null:Number(v);save();render();break;}case'reset-sim':if(confirm('Bỏ các giả định và lấy lại dữ liệu thực tế?')){scenario=structuredClone(data());render();}break;case'sim-done':{const v=Number($('#sim-done').value);if(v>=0&&Number.isInteger(v)){scenario.settings.done=v;render();}else toast('Số hồ sơ phải là số nguyên không âm.');break;}case'export':exportData();break;case'import':$('#import-file').click();break;}});save();render();
